export function getAllBlogPosts(): BlogPost[] {
  return BLOG_POSTS;
}

export function getBlogPost(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find(p => p.slug === slug || p.slug === slug.replace(/^\/+|\/+$/g, ""));
}

export function getRelatedPosts(currentSlug: string, count: number = 3): BlogPost[] {
  const current = getBlogPost(currentSlug);
  const otherPosts = BLOG_POSTS.filter(p => p.slug !== currentSlug);
  if (!current) return otherPosts.slice(0, count);
  
  const sameCat = otherPosts.filter(p => p.category === current.category);
  if (sameCat.length >= count) return sameCat.slice(0, count);
  return [...sameCat, ...otherPosts.filter(p => p.category !== current.category)].slice(0, count);
}
